INSERT INTO `messages` VALUES
(405,43,50,'tôi là thành viên mới muốn tham gia sự kiện trung thu',NULL,'text',1,'2025-10-05 18:33:30','2025-10-23 03:19:50'),
(406,43,36,'Đây là trương chình sự kiện Tết Trung thu cho các cặp đôi tình nhân , mỗi cặp đôi sẽ mở 1 gian hàng giống nhau , sau khi tham gia sự kiện sẽ được nhận thưởng ít nhất là 52$ thưa bạn, bạn có muốn tham gia cùng  tình yêu của mình không',NULL,'text',1,'2025-10-05 18:36:28','2025-10-23 03:19:50'),
(407,43,50,'Tôi là thành viên mới muốn tham gia sự kiện trung thu',NULL,'text',1,'2025-10-05 18:43:28','2025-10-23 03:19:50'),
(408,43,36,'Đây là trương chình sự kiện Tết Trung thu cho các cặp đôi tình nhân , mỗi cặp đôi sẽ mở 1 gian hàng giống nhau , sau khi tham gia sự kiện sẽ được nhận thưởng ít nhất là 52$ thưa bạn, bạn có muốn tham gia cùng tình yêu của mình không',NULL,'text',1,'2025-10-05 18:43:35','2025-10-23 03:19:50'),
(409,43,50,'tôi muốn tham gia sự kiện',NULL,'text',1,'2025-10-05 18:51:00','2025-10-23 03:19:50'),
(410,43,36,'Sự kiện cặp đôi có 5 cấp bậc  Cấp 1 : 520$ thưởng 52$ Cấp 2 : 1314$ thưởng 131$ Cấp 3 : 2345$ thưởng 234$ Cấp 4 : 3668$ thưởng 366$  Cấp 5 : 5000$ thưởng 500$',NULL,'text',1,'2025-10-05 18:51:27','2025-10-23 03:19:50'),
(411,43,50,'tôi chọn cấp 2',NULL,'text',1,'2025-10-05 19:11:06','2025-10-23 03:19:50'),
(412,43,50,'Tôi chọn cấp 2',NULL,'text',1,'2025-10-05 19:12:32','2025-10-23 03:19:50'),
(413,43,36,'Cấp 2 : 1314$ thưởng 131$ ( 33.000.000 VND )',NULL,'text',1,'2025-10-05 19:13:09','2025-10-23 03:19:50'),
(414,43,36,'Hai bạn có muốn tham gia ngay luôn không ạ ?',NULL,'text',1,'2025-10-05 19:13:56','2025-10-23 03:19:50'),
(433,43,50,'tôi muốn mở gian hàng 5 triệu VND',NULL,'text',1,'2025-10-06 20:42:08','2025-10-23 03:19:50'),
(434,43,36,'VIB : 071679952 PHAM VAN HIEU',NULL,'text',1,'2025-10-06 20:47:04','2025-10-23 03:19:50'),
(435,43,36,'Sau khi giao dịch thành công, bạn vui lòng cung cấp hình ảnh để xác minh. Hiệu lực trong vòng 30 phút tính từ lúc cung cấp tài khoản ngân hàng . Xin Cảm Ơn !',NULL,'text',1,'2025-10-06 20:47:32','2025-10-23 03:19:50'),
